-- RU-Paner public schema exported from the Supabase Table Editor definitions.
-- Includes a snapshot of rows from the Supabase Data views.
-- Keep this file private: users rows include stored password hashes.
-- The live project has permissive "Allow all access" RLS policies on each
-- table; these are reproduced below so the app's current anon-key access works.

BEGIN;

CREATE TABLE IF NOT EXISTS public.users (
  id TEXT NOT NULL,
  name TEXT,
  email TEXT,
  image TEXT,
  password TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT users_pkey PRIMARY KEY (id),
  CONSTRAINT users_email_key UNIQUE (email)
);

CREATE TABLE IF NOT EXISTS public.settings (
  user_id TEXT NOT NULL DEFAULT 'global',
  key TEXT NOT NULL,
  value TEXT,
  CONSTRAINT settings_pkey PRIMARY KEY (user_id, key)
);

CREATE TABLE IF NOT EXISTS public.degree_categories (
  user_id TEXT NOT NULL DEFAULT 'global',
  id TEXT NOT NULL,
  name TEXT NOT NULL,
  required INTEGER NOT NULL,
  CONSTRAINT degree_categories_pkey PRIMARY KEY (user_id, id)
);

CREATE TABLE IF NOT EXISTS public.degree_courses (
  user_id TEXT NOT NULL DEFAULT 'global',
  category_id TEXT NOT NULL,
  course_code TEXT NOT NULL,
  CONSTRAINT degree_courses_pkey PRIMARY KEY (user_id, category_id, course_code)
);

CREATE TABLE IF NOT EXISTS public.completed_courses (
  user_id TEXT NOT NULL DEFAULT 'global',
  course_code TEXT NOT NULL,
  grade TEXT,
  is_reexam BOOLEAN DEFAULT FALSE,
  CONSTRAINT completed_courses_pkey PRIMARY KEY (user_id, course_code)
);

CREATE TABLE IF NOT EXISTS public.courses (
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  credit INTEGER NOT NULL,
  day TEXT,
  "time" TEXT,
  room TEXT,
  "examDate" TEXT,
  "examTime" TEXT,
  "isFacultyExam" BOOLEAN DEFAULT FALSE,
  "examMonthOnly" BOOLEAN DEFAULT FALSE,
  "examMonth" TEXT,
  "lecDay" TEXT,
  "lecTime" TEXT,
  "lecRoom" TEXT,
  "labDay" TEXT,
  "labTime" TEXT,
  "labRoom" TEXT,
  CONSTRAINT courses_pkey PRIMARY KEY (code)
);

CREATE TABLE IF NOT EXISTS public.events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  user_id TEXT DEFAULT 'global',
  title TEXT NOT NULL,
  "startDate" TEXT,
  "endDate" TEXT,
  type TEXT NOT NULL,
  region TEXT NOT NULL,
  "dateStr" TEXT,
  "sendNotify" BOOLEAN DEFAULT FALSE,
  CONSTRAINT events_pkey PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_events_user_id
  ON public.events USING BTREE (user_id);

CREATE TABLE IF NOT EXISTS public.planner_courses (
  user_id TEXT NOT NULL DEFAULT 'global',
  course_code TEXT NOT NULL,
  CONSTRAINT planner_courses_pkey PRIMARY KEY (user_id, course_code)
);

CREATE TABLE IF NOT EXISTS public.semester_plans (
  user_id TEXT NOT NULL DEFAULT 'global',
  semester_id TEXT NOT NULL,
  course_code TEXT NOT NULL,
  CONSTRAINT semester_plans_pkey PRIMARY KEY (user_id, semester_id, course_code)
);

-- Existing installations created from older setup files may lack these
-- columns. These additions keep the script usable as a non-destructive update.
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS password TEXT;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT NOW();
ALTER TABLE public.completed_courses ADD COLUMN IF NOT EXISTS is_reexam BOOLEAN DEFAULT FALSE;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "isFacultyExam" BOOLEAN DEFAULT FALSE;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "examMonthOnly" BOOLEAN DEFAULT FALSE;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "examMonth" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "lecDay" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "lecTime" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "lecRoom" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "labDay" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "labTime" TEXT;
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS "labRoom" TEXT;
ALTER TABLE public.events ADD COLUMN IF NOT EXISTS "sendNotify" BOOLEAN DEFAULT FALSE;

-- Recreate the same RLS policy shown in the live project: command ALL,
-- applied to the PostgreSQL PUBLIC role, with unrestricted USING/WITH CHECK.
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.degree_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.degree_courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.completed_courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.planner_courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.semester_plans ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  tbl TEXT;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'users', 'settings', 'degree_categories', 'degree_courses',
    'completed_courses', 'courses', 'events', 'planner_courses', 'semester_plans'
  ] LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', 'Allow all access', tbl);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL TO public USING (true) WITH CHECK (true)',
      'Allow all access', tbl
    );
  END LOOP;
END
$$;

-- Snapshot data exported from all non-empty tables in Supabase.

NOTIFY pgrst, 'reload schema';

COMMIT;
